    egress::Union{Absent,Union{Nothing,Vector{IoK8sApiNetworkingV1NetworkPolicyEgressRule}}} = ABSENT
    ingress::Union{Absent,Union{Nothing,Vector{IoK8sApiNetworkingV1NetworkPolicyIngressRule}}} = ABSENT
