    _openapi_values[:pretty] = pretty
    _openapi_values[:dryrun] = dryrun
    _openapi_values[:graceperiodseconds] = graceperiodseconds
    _openapi_values[:ignorestorereaderrorwithclusterbreakingpotential] = ignorestorereaderrorwithclusterbreakingpotential
    _openapi_values[:orphandependents] = orphandependents
    _openapi_values[:propagationpolicy] = propagationpolicy
